import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.Cyu1VozZ.js";const u=JSON.parse('{"title":"Templates","description":"","frontmatter":{},"headers":[],"relativePath":"guide/templates.md","filePath":"guide/templates.md"}'),s={name:"guide/templates.md"};function i(r,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h1><p>Publish a document as a template and other people can start their own copy of it. Using a template never touches the original: the person who uses it gets a new document in their own workspace, and edits it from there.</p><p>Any document type can be published — sheets, documents, presentations, notes, boards, and uploaded files alike.</p><h2 id="publish-a-document-as-a-template" tabindex="-1">Publish a document as a template <a class="header-anchor" href="#publish-a-document-as-a-template" aria-label="Permalink to &quot;Publish a document as a template&quot;">​</a></h2><ol><li>Open the document and click <strong>Share</strong> in the editor header</li><li>Scroll to the <strong>Template</strong> section at the bottom of the dialog</li><li>Choose who it is for — <strong>Listed in this workspace</strong> or <strong>Anyone with the link</strong></li><li>Click <strong>Publish as template</strong></li></ol><p>The template link (<code>/t/&lt;id&gt;</code>) is created and copied to your clipboard. A picture of the document is taken from the open editor and attached to the card; if that is not possible the card falls back to the document-type icon.</p><p>Only the document&#39;s <strong>author</strong> or an <strong>owner</strong> of its workspace can publish — the same authority it takes to create an editor share link, and for the same reason: a template hands the content to an audience that workspace membership no longer bounds. The rule is enforced on the server, not just in the dialog.</p><p>Everyone else is not shown the controls at all. A member who can&#39;t publish sees no <strong>Template</strong> section in the Share dialog while the document has no listing; once it has one, they see the card&#39;s title, how many times it has been used, and a button to copy its link — but nothing to publish, edit, submit, or unpublish it.</p><p>A document has at most one listing. Publishing again updates the one that exists rather than creating a second, and the link stays the same.</p><div class="warning custom-block"><p class="custom-block-title">Sheets connected to external data cannot be published</p><p>A datasource or lakehouse tab points at a connection that belongs to <em>your</em> workspace, so it would be empty for anyone who used the template. Publishing refuses such a sheet and names the tabs responsible. This is checked again when someone uses the template, so connecting a tab after publishing stops the template working rather than handing out a dead tab.</p></div><h3 id="tune-the-card" tabindex="-1">Tune the card <a class="header-anchor" href="#tune-the-card" aria-label="Permalink to &quot;Tune the card&quot;">​</a></h3><p>Once a listing exists, the same section lets you set its <strong>category</strong> (from a fixed list) and <strong>tags</strong> (freeform, comma-separated — they are lowercased, de-duplicated, and capped at ten), change its visibility, and take a fresh picture with <strong>Update preview</strong>. A thumbnail is a snapshot, not a live render, so it goes stale as you edit the document; <strong>Update preview</strong> is how you refresh it, and it is offered only while an editor that can take the picture is open.</p><p>The card&#39;s title comes from the document&#39;s title at publish time. There is no description field in the dialog today.</p><p><strong>Unpublish</strong> (the bin icon) removes the card and revokes its preview link. The document itself is untouched.</p><h2 id="the-three-tiers" tabindex="-1">The three tiers <a class="header-anchor" href="#the-three-tiers" aria-label="Permalink to &quot;The three tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Visibility</th><th>Who can find it</th></tr></thead><tbody><tr><td><strong>Anyone with the link</strong></td><td>Only people you send the link to. The listing appears in no gallery — holding the link is the whole of the access.</td></tr><tr><td><strong>This workspace</strong></td><td>Listed in the workspace&#39;s <strong>Templates</strong> tab for every member, and usable by anyone holding the link as well.</td></tr><tr><td><strong>Public</strong></td><td>Listed in the public gallery for anyone, signed in or not. Reached only through review — see below.</td></tr></tbody></table><p>You can change a listing between the first two at any time from the Share dialog. <strong>Public</strong> is never something you set yourself.</p><h2 id="browse-templates" tabindex="-1">Browse templates <a class="header-anchor" href="#browse-templates" aria-label="Permalink to &quot;Browse templates&quot;">​</a></h2><ul><li><strong>Workspace → Templates</strong> in the sidebar lists the templates published in that workspace, with the public gallery on a second tab. Choosing a card opens its template page.</li><li><strong>/templates</strong> is the public gallery on its own, and it renders for someone who has never signed in. Choosing a card opens its template page; only <em>using</em> one needs an account.</li><li><strong>New → New from template</strong> on a workspace&#39;s documents list opens a picker with the same two tabs. This one creates the document immediately, into the workspace and folder you are looking at.</li></ul><p>Every gallery has a search box, filters for document type and category, and a sort between <strong>Most used</strong> and <strong>Newest</strong>. Results load a page at a time with <strong>Load more</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A card shows how many times a template has been used. Uses by the publisher themselves are not counted.</p></div><h2 id="use-a-template" tabindex="-1">Use a template <a class="header-anchor" href="#use-a-template" aria-label="Permalink to &quot;Use a template&quot;">​</a></h2><p>The template page (<code>/t/&lt;id&gt;</code>) shows the title, who shared it, the document type, the use count, and the picture. <strong>Preview</strong> opens the real read-only viewer on the actual document, rather than a screenshot.</p><p>Click <strong>Use this template</strong> and pick a destination workspace. You get:</p><ul><li><strong>A new document of your own</strong>, named after the template. If you already have a document by that name in the destination, the new one gets a <code>(2)</code>, <code>(3)</code> suffix rather than a &quot;(copy)&quot; — a document started from a <em>Weekly Report</em> template is a weekly report, not a copy of one.</li><li><strong>Authored by you</strong>, in the workspace you chose. Started from the <strong>New from template</strong> picker instead, it lands in the folder you were viewing.</li><li><strong>The content only.</strong> Comments, share links, and version history are not carried over; the new document starts its own.</li></ul><p>If you are not signed in, the button reads <strong>Sign in to use this template</strong> and brings you back to the same page afterwards.</p><div class="warning custom-block"><p class="custom-block-title">A template you may not see reports as missing</p><p>Opening a template you are not allowed to see gives you <strong>Template not found</strong>, the same answer as a link that never existed — whether a workspace has published a template is itself workspace information. If a colleague&#39;s link does not open for you, ask them which tier it is on rather than assuming the link is broken.</p></div><h2 id="the-public-gallery" tabindex="-1">The public gallery <a class="header-anchor" href="#the-public-gallery" aria-label="Permalink to &quot;The public gallery&quot;">​</a></h2><p>The public tier is the only one that goes through review.</p><p><strong>To submit:</strong> open the document&#39;s Share dialog and use <strong>Submit for review</strong> in the <strong>Public gallery</strong> box. Submitting states what it costs you: your username and profile picture appear on the card, and you grant anyone permission to copy and modify the content.</p><p>Submitting changes nothing anyone else can observe. Your listing keeps working at the tier it already had, and links you have handed out keep resolving; only a reviewer&#39;s approval moves it to the public tier.</p><p>While a submission is pending you cannot change the card&#39;s title, category, or picture — a reviewer is looking at a fixed thing. The listing&#39;s own panel shows where the submission stands, along with whatever note the reviewer left, and that panel is the durable copy of the decision. (Notifications about approvals, rejections, and takedowns also reach the bell in the header — see <a href="./collaboration.html#notifications">Collaboration &amp; Sharing</a>.)</p><h3 id="rejection-and-takedown-are-different" tabindex="-1">Rejection and takedown are different <a class="header-anchor" href="#rejection-and-takedown-are-different" aria-label="Permalink to &quot;Rejection and takedown are different&quot;">​</a></h3><ul><li>A <strong>rejection</strong> says the submission did not make the gallery&#39;s bar. Your listing keeps working exactly as it did before you submitted, at its existing tier. You can act on the reviewer&#39;s note and use <strong>Submit again</strong>.</li><li>A <strong>takedown</strong> says the content may not be served at all. The listing stops answering for everyone but you, its preview link is revoked, and it cannot be used, re-submitted, re-published, edited, or unpublished. Your own document is untouched, and you can still copy or share it by other means.</li></ul><h3 id="once-a-template-is-public" tabindex="-1">Once a template is public <a class="header-anchor" href="#once-a-template-is-public" aria-label="Permalink to &quot;Once a template is public&quot;">​</a></h3><p>A public listing tracks the live document, so editing that document takes the card out of the gallery and back into the review queue until someone looks again. Changing the card&#39;s title, category, or picture does the same. That is deliberate: the gallery should only show what a reviewer actually approved.</p><p>Anyone signed in can <strong>report</strong> a public template from its page, choosing a reason. A report is a message to a reviewer and nothing else — it does not hide the listing or count toward any threshold.</p><div class="warning custom-block"><p class="custom-block-title">The public tier depends on deployment configuration</p><p>Public templates need the deployment to have designated reviewers and to have a particular security setting switched on. Where either is missing, <strong>Submit for review</strong> fails with a message saying which — nothing is left silently pending. The workspace and link tiers are unaffected and work on every deployment.</p></div><p>Deployments that do designate reviewers give them a queue at <code>/admin/templates</code> listing pending submissions and open reports, where each can be approved, rejected, or taken down. Closing a report is a separate action from deciding the listing, so a report can be dismissed without removing anything.</p>',39)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
